// Command-mux core: priority selection, obstacle guard, speed / acceleration limits.
// Header-only, no ROS: the same functions are used by the node (src/cmd_vel_mux_node.cpp), the golden-vector test and the
// benchmark. It is a line-by-line port of scripts/cmd_vel_mux.py: test/test_mux_golden.cpp checks that both give the same
// numbers on thousands of random inputs generated by the Python code (tools/gen_mux_golden.py).
#pragma once

#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <utility>
#include <vector>

namespace mux
{

constexpr double kPi = 3.14159265358979323846;

enum Source { kTeleop = 0, kNav = 1, kAuto = 2, kNone = 3 };   // priority order, like PRIORITY in the Python mux

struct Command { double lin = 0.0; double ang = 0.0; };

struct Received { bool valid = false; double t = 0.0; Command cmd; };

struct Params
{
  double stop_dist = 0.38, slow_dist = 1.0, rear_stop_dist = 0.3;
  bool require_scan = true;
  double max_linear = 0.6, max_angular = 2.0, max_accel = 1.2, max_ang_accel = 4.0;
};

// First fresh source in priority order. Returns the source and its command, or (kNone, 0, 0).
inline std::pair<Source, Command> select(
  const std::array<Received, 3> & last, double now, const std::array<double, 3> & timeouts)
{
  for (int s = 0; s < 3; ++s) {
    if (last[s].valid && now - last[s].t <= timeouts[s]) {
      return {static_cast<Source>(s), last[s].cmd};
    }
  }
  return {kNone, Command{}};
}

// Smallest valid range within +-cone_deg of the direction center_deg (0 = ahead, 180 = behind); rmax if none.
inline double front_distance(
  const float * ranges, std::size_t n, double angle_min, double inc, double cone_deg,
  double rmax = 12.0, double center_deg = 0.0)
{
  double best = rmax;
  if (n == 0 || inc == 0.0) {return best;}
  const double half = cone_deg * kPi / 180.0, c = center_deg * kPi / 180.0;
  for (std::size_t i = 0; i < n; ++i) {
    const double a = angle_min + static_cast<double>(i) * inc;
    const double d = std::fabs(std::atan2(std::sin(a - c), std::cos(a - c)));
    if (d <= half) {
      const double r = static_cast<double>(ranges[i]);
      if (std::isfinite(r) && r > 0.01 && r < best) {best = r;}
    }
  }
  return best;
}

// Same result as front_distance(), but the beams inside the cone are worked out once and reused while the scan geometry
// (n, angle_min, increment) stays the same, which it does for a real lidar. No trigonometry in the per-scan loop.
class ConeFinder
{
public:
  ConeFinder(double cone_deg, double center_deg, double rmax = 12.0)
  : cone_deg_(cone_deg), center_deg_(center_deg), rmax_(rmax) {}

  double operator()(const float * ranges, std::size_t n, double angle_min, double inc, double rmax)
  {
    if (n == 0 || inc == 0.0) {return rmax;}
    if (n != n_ || angle_min != angle_min_ || inc != inc_) {rebuild(n, angle_min, inc);}
    double best = rmax;
    for (const std::uint32_t i : idx_) {
      const double r = static_cast<double>(ranges[i]);
      if (std::isfinite(r) && r > 0.01 && r < best) {best = r;}
    }
    return best;
  }
  double operator()(const float * ranges, std::size_t n, double angle_min, double inc) {return (*this)(ranges, n, angle_min, inc, rmax_);}

private:
  void rebuild(std::size_t n, double angle_min, double inc)
  {
    n_ = n; angle_min_ = angle_min; inc_ = inc;
    idx_.clear();
    const double half = cone_deg_ * kPi / 180.0, c = center_deg_ * kPi / 180.0;
    for (std::size_t i = 0; i < n; ++i) {
      const double a = angle_min + static_cast<double>(i) * inc;
      if (std::fabs(std::atan2(std::sin(a - c), std::cos(a - c))) <= half) {idx_.push_back(static_cast<std::uint32_t>(i));}
    }
  }
  double cone_deg_, center_deg_, rmax_;
  std::size_t n_ = 0;
  double angle_min_ = 0.0, inc_ = 0.0;
  std::vector<std::uint32_t> idx_;
};

struct Guarded { double lin; double ang; const char * reason; };

// Obstacle guard: forward motion is limited, turning on the spot is always allowed, reversing checks the rear.
inline Guarded guard(double lin, double ang, double front, bool scan_ok, const Params & p, double rear = 12.0)
{
  if (lin == 0.0) {return {lin, ang, ""};}
  if (!scan_ok && p.require_scan) {return {0.0, ang, "no-scan"};}
  if (lin < 0.0) {
    if (rear <= p.rear_stop_dist) {return {0.0, ang, "obstacle-behind"};}
    return {lin, ang, ""};
  }
  if (front <= p.stop_dist) {return {0.0, ang, "obstacle"};}
  if (front < p.slow_dist) {
    const double k = (front - p.stop_dist) / std::max(p.slow_dist - p.stop_dist, 1e-6);
    return {lin * k, ang, "slowing"};
  }
  return {lin, ang, ""};
}

inline double ramp(double current, double target, double max_step)
{
  if (target > current) {return std::min(target, current + max_step);}
  return std::max(target, current - max_step);
}

// One control tick of speed + acceleration limits. brake = true: stop quickly.
inline Command limit_step(const Command & cur, const Command & tgt, double dt, const Params & p, bool brake)
{
  const double lin = std::max(-p.max_linear, std::min(p.max_linear, tgt.lin));
  const double ang = std::max(-p.max_angular, std::min(p.max_angular, tgt.ang));
  double lin_step, ang_step;
  if (brake) {
    lin_step = ang_step = 10.0 * dt;
  } else {
    lin_step = p.max_accel * dt;
    ang_step = p.max_ang_accel * dt;
    if (std::fabs(lin) < std::fabs(cur.lin)) {lin_step = std::max(lin_step, 2.0 * p.max_accel * dt);}
    if (std::fabs(ang) < std::fabs(cur.ang)) {ang_step = std::max(ang_step, 2.0 * p.max_ang_accel * dt);}
  }
  return {ramp(cur.lin, lin, lin_step), ramp(cur.ang, ang, ang_step)};
}

inline bool is_braking(const char * reason)
{
  const std::string r(reason);
  return r == "obstacle" || r == "obstacle-behind" || r == "no-scan";
}

}  // namespace mux
